,{"exercise_code":"GK-PRA-030","physical_objective_code":"FIS-012","ruolo":"Secondario","peso":4,"motivazione":"Il movimento richiede produzione rapida di forza sul piano orizzontale/in avanti.","attivo":true},{"exercise_code":"GK-PRA-031","physical_objective_code":"FIS-019","ruolo":"Principale","peso":5,"motivazione":"La sequenza richiede arresto, recupero posturale e nuova accelerazione.","attivo":true},{"exercise_code":"GK-PRA-031","physical_objective_code":"FIS-013","ruolo":"Secondario","peso":4,"motivazione":"Il gesto richiede una spinta esplosiva sul piano laterale.","attivo":true},{"exercise_code":"GK-PRA-031","physical_objective_code":"FIS-014","ruolo":"Secondario","peso":4,"motivazione":"La spinta del tuffo è prevalentemente monopodalica.","attivo":true},{"exercise_code":"GK-PRA-031","physical_objective_code":"FIS-027","ruolo":"Secondario","peso":4,"motivazione":"La componente laterale richiede produzione reattiva di forza e controllo del contatto.","attivo":true},{"exercise_code":"GK-PRA-031","physical_objective_code":"FIS-012","ruolo":"Secondario","peso":4,"motivazione":"Il movimento richiede produzione rapida di forza sul piano orizzontale/in avanti.","attivo":true},{"exercise_code":"GK-PRA-032","physical_objective_code":"FIS-021","ruolo":"Principale","peso":5,"motivazione":"La risposta è condizionata da uno stimolo visivo trasformato rapidamente in azione.","attivo":true},{"exercise_code":"GK-PRA-032","physical_objective_code":"FIS-012","ruolo":"Secondario","peso":4,"motivazione":"Il movimento richiede produzione rapida di forza sul piano orizzontale/in avanti.","attivo":true},{"exercise_code":"GK-PRA-032","physical_objective_code":"FIS-019","ruolo":"Secondario","peso":4,"motivazione":"La sequenza richiede arresto, recupero posturale e nuova accelerazione.","attivo":true},{"exercise_code":"GK-PRA-032","physical_objective_code":"FIS-017","ruolo":"Secondario","peso":4,"motivazione":"La qualità dei piccoli appoggi condiziona la rapidità di ritorno in guard