n guardia.","attivo":true},{"exercise_code":"GK-PRA-036","physical_objective_code":"FIS-023","ruolo":"Secondario","peso":4,"motivazione":"La sequenza richiede reazioni rapide verso soluzioni o direzioni successive.","attivo":true},{"exercise_code":"GK-PRA-037","physical_objective_code":"FIS-021","ruolo":"Principale","peso":5,"motivazione":"La risposta è condizionata da uno stimolo visivo trasformato rapidamente in azione.","attivo":true},{"exercise_code":"GK-PRA-037","physical_objective_code":"FIS-012","ruolo":"Secondario","peso":4,"motivazione":"Il movimento richiede produzione rapida di forza sul piano orizzontale/in avanti.","attivo":true},{"exercise_code":"GK-PRA-037","physical_objective_code":"FIS-019","ruolo":"Secondario","peso":4,"motivazione":"La sequenza richiede arresto, recupero posturale e nuova accelerazione.","attivo":true},{"exercise_code":"GK-PRA-037","physical_objective_code":"FIS-017","ruolo":"Secondario","peso":4,"motivazione":"La qualità dei piccoli appoggi condiziona la rapidità di ritorno in guardia.","attivo":true},{"exercise_code":"GK-PRA-037","physical_objective_code":"FIS-023","ruolo":"Secondario","peso":4,"motivazione":"La sequenza richiede reazioni rapide verso soluzioni o direzioni successive.","attivo":true},{"exercise_code":"GK-PRA-038","physical_objective_code":"FIS-019","ruolo":"Principale","peso":5,"motivazione":"La sequenza richiede arresto, recupero posturale e nuova accelerazione.","attivo":true},{"exercise_code":"GK-PRA-038","physical_objective_code":"FIS-013","ruolo":"Secondario","peso":4,"motivazione":"Il gesto richiede una spinta esplosiva sul piano laterale.","attivo":true},{"exercise_code":"GK-PRA-038","physical_objective_code":"FIS-014","ruolo":"Secondario","peso":4,"motivazione":"La spinta del tuffo è prevalentemente monopodalica.","attivo":true},{"exercise_code":"GK-PRA-038","physical_objective_code":"FIS-027","ruolo":"Secondario","peso":4,"motivazione":"La componente laterale richiede produzione reattiva di forza e controllo del contatto.","attivo":true},{"exercise_code":"GK-PRA-038","physical_objective_code":"FIS-017","ruolo":"Secondario","peso":4,"motivazione":"La qualità dei piccoli appoggi condiziona la rapidità di ritorno in guardia.","attivo":true},{"exercise_code":"GK-PRA-039","physical_objective_code":"FIS-019","ruolo":"Principale","peso":5,"motivazione":"La sequenza richiede arresto, recupero posturale e nuova accelerazione.","attivo":true},{"exercise_code":"GK-PRA-039","physical_objective_code":"FIS-012","ruolo":"Secondario","peso":4,"motivazione":"Il movimento richiede produzione rapida di forza sul piano orizzontale/in avanti.","attivo":true},{"exercise_code":"GK-PRA-039","physical_objective_code":"FIS-020","ruolo":"Secondario","peso":4,"motivazione":"Il compito richiede spostamento e riallineamento in direzioni differenti.","attivo":true},{"exercise_code":"GK-PRA-039","physical_objective_code":"FIS-017","ruolo":"Secondario","peso":4,"motivazione":"La qualità dei piccoli appoggi condiziona la rapidità di ritorno in guardia.","attivo":true},{"exercise_code":"GK-PRA-039","physical_objective_code":"FIS-023","ruolo":"Secondario","peso":4,"motivazione":"La sequenza richiede reazioni rapide verso soluzioni o direzioni successive.","attivo":true},{"exercise_code":"GK-PRA-040","physical_objective_code":"FIS-019","ruolo":"Principale","peso":5,"motivazione":"La sequenza richiede arresto, recupero posturale e nuova accelerazione.","attivo":true},{"exercise_code":"GK-PRA-040","physical_objective_code":"FIS-011","ruolo":"Secondario","peso":4,"motivazione":"La componente dominante è la produzione rapida di forza verticale per elevazione e presa alta.","attivo":true},{"exercise_code":"GK-PRA-040","physical_objective_code":"FIS-025","ruolo":"Secondario","peso":4,"motivazione":"Il gesto utilizza il ciclo stiramento-accorciamento in direzione verticale.","attivo":true},{"exercise_code":"GK-PRA-040","physical_objective_code":"FIS-017","ruolo":"Secondario","peso":4,"motivazione":"La qualità dei piccoli appoggi condiziona la rapidità di ritorno in guardia.","attivo":true},{"exercise_code":"GK-PRA-040","physical_objective_code":"FIS-023","ruolo":"Secondario","peso":4,"motivazione":"La sequenza richiede reazioni rapide verso soluzioni o direzioni successive.","attivo":true}]$mapping_json$::jsonb;
  source_count integer;
  source_pair_count integer;
  source_exercise_count integer;
  source_primary_count integer;
  unresolved_exercises integer;
  unresolved_objectives integer;
  conflicting_extra_primary integer;
  existing_count integer;
  pending_count integer;
  imported_count integer;
  exact_match_count integer;
  imported_primary_count integer;
  total_database_count integer;
begin
  if to_regclass('public.exercises') is null
     or to_regclass('public.physical_objectives') is null
     or to_regclass('public.exercise_physical_objectives') is null then
    raise exception 'FASE E annullata: mancano una o più tabelle richieste.';
  end if;

  select
    count(*),
    count(distinct (source.exercise_code, source.physical_objective_code)),
    count(distinct source.exercise_code),
    count(*) filter (where source.ruolo = 'Principale')
  into source_count, source_pair_count, source_exercise_count, source_primary_count
  from jsonb_to_recordset(mapping_data) as source(
    exercise_code text,
    physical_objective_code text,
    ruolo text,
    peso integer,
    motivazione text,
    attivo boolean
);

  if source_count <> 1985 or source_pair_count <> 1985 then
    raise exception 'FASE E annullata: attese 1.985 coppie univoche, trovate % righe e % coppie.', source_count, source_pair_count;
  end if;

  if source_exercise_count <> 460 or source_primary_count <> 460 then
    raise exception 'FASE E annullata: attesi 460 esercizi e 460 obiettivi Principali, trovati % e %.', source_exercise_count, source_primary_count;
  end if;

  if exists (
    select 1
    from jsonb_to_recordset(mapping_data) as source(
    exercise_code text,
    physical_objective_code text,
    ruolo text,
    peso integer,
    motivazione text,
    attivo boolean
)
    where source.ruolo not in ('Principale', 'Secondario', 'Complementare')
       or source.peso not between 1 and 5
       or source.exercise_code is null
       or source.physical_objective_code is null
       or source.motivazione is null
  ) then
    raise exception 'FASE E annullata: ruolo, peso o campi obbligatori non validi.';
  end if;

  if exists (
    select source.exercise_code
    from jsonb_to_recordset(mapping_data) as source(
    exercise_code text,
    physical_objective_code text,
    ruolo text,
    peso integer,
    motivazione text,
    attivo boolean
)
    where source.ruolo = 'Principale'
    group by source.exercise_code
    having count(*) <> 1
  ) then
    raise exception 'FASE E annullata: almeno un esercizio non ha esattamente un obiettivo Principale.';
  end if;

  select count(*) into unresolved_exercises
  from (
    select distinct source.exercise_code
    from jsonb_to_recordset(mapping_data) as source(
    exercise_code text,
    physical_objective_code text,
    ruolo text,
    peso integer,
    motivazione text,
    attivo boolean
)
  ) as codes
  left join public.exercises as exercise on exercise.codice = codes.exercise_code
  where exercise.id is null;

  select count(*) into unresolved_objectives
  from (
    select distinct source.physical_objective_code
    from jsonb_to_recordset(mapping_data) as source(
    exercise_code text,
    physical_objective_code text,
    ruolo text,
    peso integer,
    motivazione text,
    attivo boolean
)
  ) as codes
  left join public.physical_objectives as objective on objective.codice = codes.physical_objective_code
  where objective.id is null;

  if unresolved_exercises <> 0 or unresolved_objectives <> 0 then
    raise exception 'FASE E annullata: % codici esercizio e % codici FIS non risolti.', unresolved_exercises, unresolved_objectives;
  end if;

  -- Protegge eventuali associazioni extra: non vengono eliminate o modificate.
  -- Se una extra è già Principale sullo stesso esercizio, l'import viene annullato.
  select count(*) into conflicting_extra_primary
  from public.exercise_physical_objectives as mapping
  join public.exercises as exercise on exercise.id = mapping.exercise_id
  join public.physical_objectives as objective on objective.id = mapping.physical_objective_id
  where mapping.ruolo = 'Principale'
    and exercise.codice in (
      select distinct source.exercise_code
      from jsonb_to_recordset(mapping_data) as source(
    exercise_code text,
    physical_objective_code text,
    ruolo text,
    peso integer,
    motivazione text,
    attivo boolean
)
    )
    and not exists (
      select 1
      from jsonb_to_recordset(mapping_data) as source(
    exercise_code text,
    physical_objective_code text,
    ruolo text,
    peso integer,
    motivazione text,
    attivo boolean
)
      where source.exercise_code = exercise.codice
        and source.physical_objective_code = objective.codice
    );

  if conflicting_extra_primary <> 0 then
    raise exception 'FASE E annullata: % mappature extra con ruolo Principale richiedono una verifica manuale.', conflicting_extra_primary;
  end if;

  select count(*) into existing_count
  from jsonb_to_recordset(mapping_data) as source(
    exercise_code text,
    physical_objective_code text,
    ruolo text,
    peso integer,
    motivazione text,
    attivo boolean
)
  join public.exercises as exercise on exercise.codice = source.exercise_code
  join public.physical_objectives as objective on objective.codice = source.physical_objective_code
  join public.exercise_physical_objectives as mapping
    on mapping.exercise_id = exercise.id
   and mapping.physical_objective_id = objective.id;

  pending_count := source_count - existing_count;

  -- Evita conflitti temporanei con il vincolo "un solo Principale per esercizio".
  update public.exercise_physical_objectives as mapping
  set ruolo = 'Secondario',
      updated_at = now()
  from jsonb_to_recordset(mapping_data) as source(
    exercise_code text,
    physical_objective_code text,
    ruolo text,
    peso integer,
    motivazione text,
    attivo boolean
)
  join public.exercises as exercise on exercise.codice = source.exercise_code
  join public.physical_objectives as objective on objective.codice = source.physical_objective_code
  where mapping.exercise_id = exercise.id
    and mapping.physical_objective_id = objective.id
    and mapping.ruolo = 'Principale';

  insert into public.exercise_physical_objectives as target (
    exercise_id,
    physical_objective_id,
    ruolo,
    peso,
    motivazione,
    attivo
  )
  select
    exercise.id,
    objective.id,
    source.ruolo,
    source.peso,
    source.motivazione,
    source.attivo
  from jsonb_to_recordset(mapping_data) as source(
    exercise_code text,
    physical_objective_code text,
    ruolo text,
    peso integer,
    motivazione text,
    attivo boolean
)
  join public.exercises as exercise on exercise.codice = source.exercise_code
  join public.physical_objectives as objective on objective.codice = source.physical_objective_code
  on conflict (exercise_id, physical_objective_id) do update set
    ruolo = excluded.ruolo,
    peso = excluded.peso,
    motivazione = excluded.motivazione,
    attivo = excluded.attivo,
    updated_at = now();

  select count(*) into imported_count
  from jsonb_to_recordset(mapping_data) as source(
    exercise_code text,
    physical_objective_code text,
    ruolo text,
    peso integer,
    motivazione text,
    attivo boolean
)
  join public.exercises as exercise on exercise.codice = source.exercise_code
  join public.physical_objectives as objective on objective.codice = source.physical_objective_code
  join public.exercise_physical_objectives as mapping
    on mapping.exercise_id = exercise.id
   and mapping.physical_objective_id = objective.id;

  select count(*) into exact_match_count
  from jsonb_to_recordset(mapping_data) as source(
    exercise_code text,
    physical_objective_code text,
    ruolo text,
    peso integer,
    motivazione text,
    attivo boolean
)
  join public.exercises as exercise on exercise.codice = source.exercise_code
  join public.physical_objectives as objective on objective.codice = source.physical_objective_code
  join public.exercise_physical_objectives as mapping
    on mapping.exercise_id = exercise.id
   and mapping.physical_objective_id = objective.id
   and mapping.ruolo = source.ruolo
   and mapping.peso = source.peso
   and mapping.motivazione = source.motivazione
   and mapping.attivo = source.attivo;

  select count(*) into imported_primary_count
  from jsonb_to_recordset(mapping_data) as source(
    exercise_code text,
    physical_objective_code text,
    ruolo text,
    peso integer,
    motivazione text,
    attivo boolean
)
  join public.exercises as exercise on exercise.codice = source.exercise_code
  join public.physical_objectives as objective on objective.codice = source.physical_objective_code
  join public.exercise_physical_objectives as mapping
    on mapping.exercise_id = exercise.id
   and mapping.physical_objective_id = objective.id
  where source.ruolo = 'Principale'
    and mapping.ruolo = 'Principale';

  if imported_count <> 1985 or exact_match_count <> 1985 or imported_primary_count <> 460 then
    raise exception 'FASE E annullata: verifica finale non superata (presenti %, esatti %, principali %).', imported_count, exact_match_count, imported_primary_count;
  end if;

  if exists (
    select mapping.exercise_id, mapping.physical_objective_id
    from public.exercise_physical_objectives as mapping
    group by mapping.exercise_id, mapping.physical_objective_id
    having count(*) > 1
  ) then
    raise exception 'FASE E annullata: rilevate coppie duplicate dopo l''import.';
  end if;

  select count(*) into total_database_count
  from public.exercise_physical_objectives;

  perform set_config('keeper.phase_e_source_count', source_count::text, false);
  perform set_config('keeper.phase_e_updated_count', existing_count::text, false);
  perform set_config('keeper.phase_e_inserted_count', pending_count::text, false);
  perform set_config('keeper.phase_e_primary_count', imported_primary_count::text, false);
  perform set_config('keeper.phase_e_total_count', total_database_count::text, false);
end
$phase_e$;

commit;

select
  'FASE E COMPLETATA' as risultato,
  current_setting('keeper.phase_e_source_count')::integer as mappature_master,
  current_setting('keeper.phase_e_updated_count')::integer as mappature_aggiornate,
  current_setting('keeper.phase_e_inserted_count')::integer as mappature_inserite,
